import React, {
  useEffect,
  useState,
} from "react";

const MOVESET_PATH =
  "/csv_movesets/";

export default function PokemonBuildPanel({
  clickedBuild,
}) {
  const [
    buildData,
    setBuildData,
  ] = useState(null);

  const normalize = (str) =>
    str
      ?.toLowerCase()
      .replace(
        /[^a-z0-9]/g,
        ""
      )
      .trim() || "";

  const loadCSV = async (
    path
  ) => {
    const res =
      await fetch(path);
    return await res.text();
  };

  const parseCSV = (
    text
  ) =>
    text
      .trim()
      .split(/\r?\n/)
      .slice(1)
      .map((r) =>
        r.split(
          /,(?=(?:(?:[^"]*"){2})*[^"]*$)/
        )
      );

  useEffect(() => {
    if (
      !clickedBuild ||
      !clickedBuild.sourceFile
    ) {
      setBuildData(
        null
      );
      return;
    }

    const loadBuild =
      async () => {
        const targetFile =
          clickedBuild.sourceFile;

        console.log(
          "Clicked Build:",
          clickedBuild
        );
        console.log(
          "Exact File Used:",
          targetFile
        );

        const text =
          await loadCSV(
            MOVESET_PATH +
              targetFile
          );

        const rows =
          parseCSV(
            text
          );

        const pokemonRows =
          rows.filter(
            (r) =>
              normalize(
                r[1]
              ) ===
              normalize(
                clickedBuild.pokemon
              )
          );

        console.log(
          "Pokemon Rows Found:",
          pokemonRows.length
        );

        if (
          !pokemonRows.length
        ) {
          setBuildData(
            null
          );
          return;
        }

        const grouped =
          {};

        for (let row of pokemonRows) {
          const category =
            row[2];
          const itemName =
            row[4];
          const usage =
            row[5];

          if (
            !grouped[
              category
            ]
          ) {
            grouped[
              category
            ] = [];
          }

          grouped[
            category
          ].push({
            name:
              itemName,
            usage,
          });
        }

        Object.keys(
          grouped
        ).forEach(
          (
            cat
          ) => {
            grouped[
              cat
            ] =
              grouped[
                cat
              ]
                .sort(
                  (
                    a,
                    b
                  ) =>
                    Number(
                      b.usage
                    ) -
                    Number(
                      a.usage
                    )
                )
                .slice(
                  0,
                  5
                );
          }
        );

        setBuildData({
          pokemon:
            clickedBuild.pokemon,
          display:
            clickedBuild.display,
          month:
            clickedBuild.month,
          data: grouped,
        });
      };

    loadBuild();
  }, [
    clickedBuild,
  ]);

  if (
    !buildData
  ) {
    return (
      <div
        style={{
          padding:
            "15px",
          background:
            "#f8f8f8",
          border:
            "1px solid #ddd",
          borderRadius:
            "10px",
        }}
      >
        Click a graph point
        to view build
      </div>
    );
  }

  return (
    <div
      style={{
        padding:
          "15px",
        background:
          "#f8f8f8",
        border:
          "1px solid #ddd",
        borderRadius:
          "10px",
      }}
    >
      <h3>
        {
          buildData.display
        }{" "}
        —{" "}
        {
          buildData.month
        }
      </h3>

      {Object.entries(
        buildData.data
      ).map(
        ([
          category,
          items,
        ]) => (
          <div
            key={
              category
            }
          >
            <strong>
              {
                category
              }
            </strong>
            <ul>
              {items.map(
                (
                  item,
                  idx
                ) => (
                  <li
                    key={
                      idx
                    }
                  >
                    {
                      item.name
                    }{" "}
                    (
                    {
                      item.usage
                    }
                    %)
                  </li>
                )
              )}
            </ul>
          </div>
        )
      )}
    </div>
  );
}
